// ============================================================================
//  TunerConstants.java  -  EVERY physical number about the swerve drivetrain
// ----------------------------------------------------------------------------
//  STUDENTS: This is the file that describes YOUR robot to the code. It was
//  generated by CTRE's "Tuner X Swerve Project Generator" and then filled in
//  with the real numbers measured/tuned on the Stingray (Team 5090) robot:
//    * which CAN ID each motor and encoder has,
//    * the gear ratios and wheel size,
//    * the control gains (how hard the motors push to hit a target),
//    * where each wheel sits relative to the center of the robot.
//
//  If a wheel spins the wrong way, or a module points the wrong direction, or
//  the robot thinks it's driving faster/slower than it really is, the fix is
//  almost always a number in THIS file.
//
//  >>> IMPORTANT ONE-TIME CHECK: the CAN bus (see kCANBus below). <<<
//  These numbers came from the real Stingray robot, which used a CANivore.
//  On the SystemCore/Pi with the Waveshare CAN HAT, the devices are usually on
//  the built-in bus "can_s0". Read the kCANBus comment and pick the right one.
// ============================================================================
package frc.robot.generated;

import static org.wpilib.units.Units.*;

import com.ctre.phoenix6.CANBus;
import com.ctre.phoenix6.configs.*;
import com.ctre.phoenix6.hardware.*;
import com.ctre.phoenix6.signals.*;
import com.ctre.phoenix6.swerve.*;
import com.ctre.phoenix6.swerve.SwerveModuleConstants.*;
import org.wpilib.math.Matrix;
import org.wpilib.math.numbers.N1;
import org.wpilib.math.numbers.N3;
import org.wpilib.units.measure.*;

public class TunerConstants {
  // ==========================================================================
  //  CONTROL GAINS  (how the motors chase their targets -- tuned per robot)
  // ==========================================================================

  // STEER gains: control the angle motor that points each wheel.
  //   kP = how strongly it corrects position error (big for steering).
  //   kD = damping. kS/kV = feedforward (overcome friction / go a set speed).
  private static final Slot0Configs steerGains =
      new Slot0Configs()
          .withKP(100)
          .withKI(0)
          .withKD(0.5)
          .withKS(0.1)
          .withKV(2.66)
          .withKA(0)
          .withStaticFeedforwardSign(StaticFeedforwardSignValue.UseClosedLoopSign);

  // DRIVE gains: control the wheel-spinning motor (its speed).
  private static final Slot0Configs driveGains =
      new Slot0Configs().withKP(0.1).withKI(0).withKD(0).withKS(0.227).withKV(0.783);

  // Whether the closed-loop output is expressed as Voltage or TorqueCurrent.
  private static final ClosedLoopOutputType kSteerClosedLoopOutput = ClosedLoopOutputType.Voltage;
  private static final ClosedLoopOutputType kDriveClosedLoopOutput = ClosedLoopOutputType.Voltage;

  // The motor type inside each Kraken/Falcon (integrated TalonFX).
  private static final DriveMotorArrangement kDriveMotorType =
      DriveMotorArrangement.TalonFX_Integrated;
  private static final SteerMotorArrangement kSteerMotorType =
      SteerMotorArrangement.TalonFX_Integrated;

  // Use the CANcoder as the steering angle sensor (fused for accuracy).
  private static final SteerFeedbackType kSteerFeedbackType = SteerFeedbackType.FusedCANcoder;

  // Current (amps) at which the wheels start to slip -- limits wheel torque so
  // the robot doesn't burn rubber / brown out. Tuned on the real robot.
  private static final Current kSlipCurrent = Amps.of(70.0);

  // ==========================================================================
  //  MOTOR / ENCODER STARTING CONFIGS
  // ==========================================================================
  private static final TalonFXConfiguration driveInitialConfigs = new TalonFXConfiguration();
  private static final TalonFXConfiguration steerInitialConfigs =
      new TalonFXConfiguration()
          .withCurrentLimits(
              new CurrentLimitsConfigs()
                  // Steering doesn't need much torque, so cap its current to avoid brownouts.
                  .withStatorCurrentLimit(Amps.of(60))
                  .withStatorCurrentLimitEnable(true));
  private static final CANcoderConfiguration encoderInitialConfigs = new CANcoderConfiguration();
  private static final Pigeon2Configuration pigeonConfigs = null;

  // ==========================================================================
  //  CAN BUS  -- WHICH WIRE all the swerve devices live on. READ THIS.
  // ==========================================================================
  //  All 13 swerve devices (8 motors + 4 CANcoders + 1 Pigeon2) must be on ONE
  //  CAN bus. Pick the line that matches how YOUR robot is wired:
  //
  //   (A) SystemCore built-in CAN HAT  -> the Waveshare "can_s0" bus. This is
  //       the default for the Pi + non-FD HAT you have. Method name is all
  //       lowercase: systemcore(0)=can_s0, systemcore(1)=can_s1.
  //
  //   (B) CANivore over USB  -> use the CANivore's name. The original Stingray
  //       robot used this. Requires the CANivore driver packages installed on
  //       the SystemCore (see the main SystemCore setup guide).
  //
  //  Leave (A) active unless your Krakens are actually on a CANivore.
  public static final CANBus kCANBus = CANBus.systemcore(0); // (A) built-in HAT bus can_s0
  // public static final CANBus kCANBus = new CANBus("Default Name"); // (B) CANivore by name

  // ==========================================================================
  //  ROBOT PHYSICAL PROPERTIES  (measured on the Stingray robot)
  // ==========================================================================
  // Top speed of the robot at full battery (12 V). Used to scale joystick input.
  public static final LinearVelocity kSpeedAt12Volts = MetersPerSecond.of(5.21);

  // Coupling: how many drive-motor turns happen per 1 turn of the steering. A
  // quirk of coaxial swerve modules; correcting it keeps odometry accurate.
  private static final double kCoupleRatio = 3.5714285714285716;

  private static final double kDriveGearRatio = 6.122448979591837; // motor turns : 1 wheel turn
  private static final double kSteerGearRatio = 21.428571428571427; // motor turns : 1 module turn
  private static final Distance kWheelRadius = Inches.of(2); // wheel radius (a 4" wheel)

  // Whole-side inversions (CTRE convention): right side is mirrored from left.
  private static final boolean kInvertLeftSide = false;
  private static final boolean kInvertRightSide = true;

  private static final int kPigeonId = 0; // CAN ID of the Pigeon2 gyro

  // Simulation-only values (ignored on the real robot).
  private static final MomentOfInertia kSteerInertia = KilogramSquareMeters.of(0.01);
  private static final MomentOfInertia kDriveInertia = KilogramSquareMeters.of(0.01);
  private static final Voltage kSteerFrictionVoltage = Volts.of(0.2);
  private static final Voltage kDriveFrictionVoltage = Volts.of(0.2);

  // Bundles the drivetrain-wide constants (bus name + gyro) for CTRE.
  public static final SwerveDrivetrainConstants DrivetrainConstants =
      new SwerveDrivetrainConstants()
          .withCANBusName(kCANBus.getName())
          .withPigeon2Id(kPigeonId)
          .withPigeon2Configs(pigeonConfigs);

  // A "factory" that stamps out each module's constants from the shared settings above.
  private static final SwerveModuleConstantsFactory<
          TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>
      ConstantCreator =
          new SwerveModuleConstantsFactory<
                  TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>()
              .withDriveMotorGearRatio(kDriveGearRatio)
              .withSteerMotorGearRatio(kSteerGearRatio)
              .withCouplingGearRatio(kCoupleRatio)
              .withWheelRadius(kWheelRadius)
              .withSteerMotorGains(steerGains)
              .withDriveMotorGains(driveGains)
              .withSteerMotorClosedLoopOutput(kSteerClosedLoopOutput)
              .withDriveMotorClosedLoopOutput(kDriveClosedLoopOutput)
              .withSlipCurrent(kSlipCurrent)
              .withSpeedAt12Volts(kSpeedAt12Volts)
              .withDriveMotorType(kDriveMotorType)
              .withSteerMotorType(kSteerMotorType)
              .withFeedbackSource(kSteerFeedbackType)
              .withDriveMotorInitialConfigs(driveInitialConfigs)
              .withSteerMotorInitialConfigs(steerInitialConfigs)
              .withEncoderInitialConfigs(encoderInitialConfigs)
              .withSteerInertia(kSteerInertia)
              .withDriveInertia(kDriveInertia)
              .withSteerFrictionVoltage(kSteerFrictionVoltage)
              .withDriveFrictionVoltage(kDriveFrictionVoltage);

  // ==========================================================================
  //  THE FOUR MODULES  (Stingray CAN IDs, encoder offsets, positions)
  // --------------------------------------------------------------------------
  //  For each corner:
  //    DriveMotorId / SteerMotorId / EncoderId = the CAN IDs of that module's
  //        drive Kraken, steer Kraken, and CANcoder.
  //    EncoderOffset = the CANcoder reading (in rotations) when that wheel is
  //        pointed straight forward. This is calibrated per robot -- if a module
  //        points 90 degrees off, this number is the culprit.
  //    XPos / YPos = where the wheel is relative to robot center (+X = forward,
  //        +Y = left). Stingray is a square with wheels 11.5" out each way.
  // ==========================================================================

  // ----- Front Left -----
  private static final int kFrontLeftDriveMotorId = 40;
  private static final int kFrontLeftSteerMotorId = 30;
  private static final int kFrontLeftEncoderId = 50;
  private static final Angle kFrontLeftEncoderOffset = Rotations.of(0.227783203125);
  private static final boolean kFrontLeftSteerMotorInverted = true;
  private static final boolean kFrontLeftEncoderInverted = false;
  private static final Distance kFrontLeftXPos = Inches.of(11.5);
  private static final Distance kFrontLeftYPos = Inches.of(11.5);

  // ----- Front Right -----
  private static final int kFrontRightDriveMotorId = 41;
  private static final int kFrontRightSteerMotorId = 31;
  private static final int kFrontRightEncoderId = 51;
  private static final Angle kFrontRightEncoderOffset = Rotations.of(-0.303466796875);
  private static final boolean kFrontRightSteerMotorInverted = true;
  private static final boolean kFrontRightEncoderInverted = false;
  private static final Distance kFrontRightXPos = Inches.of(11.5);
  private static final Distance kFrontRightYPos = Inches.of(-11.5);

  // ----- Back Left -----
  private static final int kBackLeftDriveMotorId = 42;
  private static final int kBackLeftSteerMotorId = 32;
  private static final int kBackLeftEncoderId = 52;
  private static final Angle kBackLeftEncoderOffset = Rotations.of(0.12255859375);
  private static final boolean kBackLeftSteerMotorInverted = true;
  private static final boolean kBackLeftEncoderInverted = false;
  private static final Distance kBackLeftXPos = Inches.of(-11.5);
  private static final Distance kBackLeftYPos = Inches.of(11.5);

  // ----- Back Right -----
  private static final int kBackRightDriveMotorId = 43;
  private static final int kBackRightSteerMotorId = 33;
  private static final int kBackRightEncoderId = 53;
  private static final Angle kBackRightEncoderOffset = Rotations.of(-0.49609375);
  private static final boolean kBackRightSteerMotorInverted = true;
  private static final boolean kBackRightEncoderInverted = false;
  private static final Distance kBackRightXPos = Inches.of(-11.5);
  private static final Distance kBackRightYPos = Inches.of(-11.5);

  // Build the final constants object for each module using the factory above.
  public static final SwerveModuleConstants<
          TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>
      FrontLeft =
          ConstantCreator.createModuleConstants(
              kFrontLeftSteerMotorId,
              kFrontLeftDriveMotorId,
              kFrontLeftEncoderId,
              kFrontLeftEncoderOffset,
              kFrontLeftXPos,
              kFrontLeftYPos,
              kInvertLeftSide,
              kFrontLeftSteerMotorInverted,
              kFrontLeftEncoderInverted);
  public static final SwerveModuleConstants<
          TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>
      FrontRight =
          ConstantCreator.createModuleConstants(
              kFrontRightSteerMotorId,
              kFrontRightDriveMotorId,
              kFrontRightEncoderId,
              kFrontRightEncoderOffset,
              kFrontRightXPos,
              kFrontRightYPos,
              kInvertRightSide,
              kFrontRightSteerMotorInverted,
              kFrontRightEncoderInverted);
  public static final SwerveModuleConstants<
          TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>
      BackLeft =
          ConstantCreator.createModuleConstants(
              kBackLeftSteerMotorId,
              kBackLeftDriveMotorId,
              kBackLeftEncoderId,
              kBackLeftEncoderOffset,
              kBackLeftXPos,
              kBackLeftYPos,
              kInvertLeftSide,
              kBackLeftSteerMotorInverted,
              kBackLeftEncoderInverted);
  public static final SwerveModuleConstants<
          TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>
      BackRight =
          ConstantCreator.createModuleConstants(
              kBackRightSteerMotorId,
              kBackRightDriveMotorId,
              kBackRightEncoderId,
              kBackRightEncoderOffset,
              kBackRightXPos,
              kBackRightYPos,
              kInvertRightSide,
              kBackRightSteerMotorInverted,
              kBackRightEncoderInverted);

  /**
   * Swerve Drive class utilizing CTR Electronics' Phoenix 6 API. AdvantageKit's Drive subsystem
   * uses the module constants above directly, so this inner class is kept only for compatibility
   * with the generated CTRE format.
   */
  public static class TunerSwerveDrivetrain extends SwerveDrivetrain<TalonFX, TalonFX, CANcoder> {
    public TunerSwerveDrivetrain(
        SwerveDrivetrainConstants drivetrainConstants, SwerveModuleConstants<?, ?, ?>... modules) {
      super(TalonFX::new, TalonFX::new, CANcoder::new, drivetrainConstants, modules);
    }

    public TunerSwerveDrivetrain(
        SwerveDrivetrainConstants drivetrainConstants,
        double odometryUpdateFrequency,
        SwerveModuleConstants<?, ?, ?>... modules) {
      super(
          TalonFX::new,
          TalonFX::new,
          CANcoder::new,
          drivetrainConstants,
          odometryUpdateFrequency,
          modules);
    }

    public TunerSwerveDrivetrain(
        SwerveDrivetrainConstants drivetrainConstants,
        double odometryUpdateFrequency,
        Matrix<N3, N1> odometryStandardDeviation,
        Matrix<N3, N1> visionStandardDeviation,
        SwerveModuleConstants<?, ?, ?>... modules) {
      super(
          TalonFX::new,
          TalonFX::new,
          CANcoder::new,
          drivetrainConstants,
          odometryUpdateFrequency,
          odometryStandardDeviation,
          visionStandardDeviation,
          modules);
    }
  }
}
